int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->flags & CDF_DRIVE_STATUS)) {
        return -EINVAL;
    }

    if (!is_valid_operation(arg)) {
        return -EINVAL;
    }

    return cdi->ops->get_status(cdi, arg);
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capability & CDROM_CAN_GET_STATUS)) {
        return -1; // Error code indicating the drive does not support status retrieval
    }

    if (arg >= MAX_DRIVE_STATES) {
        return -1; // Error code for invalid argument
    }

    return cdi->get_status_fn(cdi, arg);
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capacity & CDC_DRIVE_STATUS)) {
        return -EINVAL;
    }

    if (arg >= CDROM_MAX_DRIVE_STATUS) {
        return -EINVAL;
    }

    return cdi->ops->drive_status(cdi, arg);
}

int cdrom_get_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capability & CDC_STATUS))
        return -EINVAL;

    if (arg >= CDROM_MAX_SLOT)
        return -EINVAL;

    if (arg == 0)
        return cdi->current_state;

    return cdi->slot_status[arg];
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capabilities & CDC_DRIVE_STATUS)) {
        return -EINVAL;
    }

    if (!can_perform_operation(cdi, arg)) {
        return -EINVAL;
    }

    return cdi->ops->get_status(cdi, arg);
}
